mapper.sql:
u.id,
#{query.tenantId} AS tenant_id,
u.tenant_id,
u.username, u.real_name,
CASE WHEN u.user_type = 0 THEN 0 WHEN sut_current.member_type = 1 THEN 1 ELSE 2 END AS user_type,
u.user_type,
u.user_client, u.email, u.phone, u.id_card, u.gender, u.password, u.salt, u.user_status, u.avatar, u.region_code, u.last_login_time, u.last_login_ip, u.login_count, u.force_password_change, u.remark, u.create_dept, u.create_by, u.create_time, u.update_by, u.update_time, u.del_flag, COALESCE(( SELECT GROUP_CONCAT(tn.tenant_name ORDER BY sut.is_default DESC, tn.id ASC SEPARATOR ',') FROM sys_user_tenant sut INNER JOIN sys_tenant tn ON tn.id = sut.tenant_id AND tn.del_flag = 0 WHERE sut.user_id = u.id AND sut.status = 1 AND tn.tenant_status = 1 ), t.tenant_name) AS tenant_name, ( SELECT GROUP_CONCAT(o.org_name ORDER BY o.sort SEPARATOR ',') FROM sys_user_org uo LEFT JOIN sys_org o ON o.id = uo.org_id AND o.tenant_id = uo.tenant_id AND o.del_flag = 0 WHERE uo.user_id = u.id
AND uo.tenant_id = #{query.tenantId}
) AS org_name, ( SELECT GROUP_CONCAT(p.post_name ORDER BY p.sort SEPARATOR ',') FROM sys_user_post up LEFT JOIN sys_post p ON p.id = up.post_id AND p.del_flag = 0 WHERE up.user_id = u.id
AND up.tenant_id = #{query.tenantId}
) AS post_name

AND u.del_flag = 0
AND EXISTS ( SELECT 1 FROM sys_user_tenant sut WHERE sut.user_id = u.id AND sut.tenant_id = #{query.tenantId} AND sut.status = 1 )
AND u.username LIKE CONCAT('%', #{query.username}, '%')
AND u.real_name LIKE CONCAT('%', #{query.realName}, '%')
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND u.user_type = #{query.userType}
AND u.phone = #{query.phone}
AND u.user_status = #{query.userStatus}
AND u.create_dept = #{query.createDept}
AND EXISTS ( SELECT 1 FROM sys_user_post up INNER JOIN sys_post p ON p.id = up.post_id AND p.tenant_id = up.tenant_id AND p.del_flag = 0 WHERE up.user_id = u.id AND up.post_id = #{query.postId}
AND up.tenant_id = #{query.tenantId}
)
AND u.id IN ( SELECT uo.user_id FROM sys_user_org uo INNER JOIN sys_org o ON o.id = uo.org_id AND o.tenant_id = uo.tenant_id AND o.del_flag = 0 WHERE
uo.tenant_id = #{query.tenantId} AND
uo.org_id = #{query.orgId} )
AND u.id IN ( SELECT uo.user_id FROM sys_user_org uo WHERE
uo.tenant_id = #{query.tenantId} AND
uo.org_id IN ( SELECT id FROM sys_org WHERE del_flag = 0 AND
tenant_id = #{query.tenantId} AND
(id = #{query.orgId} OR FIND_IN_SET(#{query.orgId}, ancestors) > 0) ) )
AND (u.region_code = REPLACE(#{query.regionCode},'ALL','') OR u.region_code IN (SELECT code FROM sys_region_code WHERE parent_code = REPLACE(#{query.regionCode},'ALL','')))
AND u.region_code = #{query.regionCode}
